const quote = $input.first().json;

const execRecord =
  $('查询执行表').first().json?.data?.items?.[0] || {};
const execFields = execRecord.fields || {};

const errors = [];

function textOf(v) {
  if (v == null || v === '') return '';
  if (typeof v === 'string' || typeof v === 'number') return String(v).trim();
  if (Array.isArray(v)) return v.map(textOf).filter(Boolean).join('；');
  if (typeof v === 'object') {
    if (Array.isArray(v.value)) return textOf(v.value);
    if (v.text != null) return String(v.text).trim();
    if (v.name != null) return String(v.name).trim();
    if (v.link != null) return String(v.link).trim();
  }
  return '';
}

function dateOf(v) {
  if (v == null || v === '') return '';
  if (typeof v === 'number') return new Date(v).toISOString().slice(0, 10);
  if (
    typeof v === 'object' &&
    Array.isArray(v.value) &&
    typeof v.value[0] === 'number'
  ) {
    return new Date(v.value[0]).toISOString().slice(0, 10);
  }
  return textOf(v);
}

function fmtYuan(n) {
  const x = Math.round(Number(n) * 100) / 100;
  if (!Number.isFinite(x)) return '0';
  return Number.isInteger(x) ? String(x) : x.toFixed(2);
}

function requireText(label, value) {
  if (value == null || String(value).trim() === '') {
    errors.push('缺少' + label);
  }
}

if (!execRecord.record_id) errors.push('未找到执行记录');

// 客户信息：单位 ； 联系人 ； 电话
const customerRaw = textOf(execFields['客户信息']);
const customerParts = customerRaw
  .split(/[；;]/)
  .map((s) => s.trim())
  .filter(Boolean);
const 单位 = customerParts[0] || '';
const 联系人 = customerParts[1] || '';
const 联系方式 = customerParts[2] || '';

const payRaw = textOf(execFields['付款比例']);
const totalCost = Number(quote.活动总价);

if (!Number.isFinite(totalCost) || totalCost <= 0) {
  errors.push('在线报价活动总价无效: ' + (quote.活动总价 ?? ''));
}

const ratios = String(payRaw || '')
  .split(/[-—–_/／]/)
  .map((s) => s.trim())
  .filter(Boolean)
  .map(Number);

let clauses = [];
if (!payRaw) {
  errors.push('缺少付款比例');
} else if (ratios.length < 3 || ratios.some((n) => !Number.isFinite(n))) {
  errors.push('付款比例格式无效，期望如 2-6-2，实际: ' + payRaw);
} else if (Number.isFinite(totalCost) && totalCost > 0) {
  const [r1, r2, r3] = ratios;
  const [p1, p2, p3] = [r1 * 10, r2 * 10, r3 * 10];
  if (p1 > 0) {
    clauses.push(
      '甲方于本合同签订之日起三个工作日内支付活动总款的' +
        p1 +
        '%作为预付款：' +
        fmtYuan((totalCost * p1) / 100) +
        '元。',
    );
  }
  if (p2 > 0) {
    clauses.push(
      '甲方于活动出发前72小时内(出发当天不包含在内)支付活动总款的' +
        p2 +
        '%：' +
        fmtYuan((totalCost * p2) / 100) +
        '元，若逾期付款，乙方有权选择单方解除合同，活动将默认取消按照违约情况赔付。',
    );
  }
  if (p3 > 0) {
    clauses.push(
      '甲方于活动结束在收到乙方开具的全额发票后，五个工作日内向乙方交纳活动余款' +
        p3 +
        '%：' +
        fmtYuan((totalCost * p3) / 100) +
        '元。',
    );
  }
  if (!clauses.length) {
    errors.push('付款比例三段均为 0，无法生成付款方式');
  }
}

const 费用明细 = Array.isArray(quote.报价明细条目) ? quote.报价明细条目 : [];
const 活动行程 = Array.isArray(quote.活动行程条目) ? quote.活动行程条目 : [];

const signingUnit = textOf(execFields['签约单位']);
const 订单号 = textOf(execFields['订单号']);
const 策划师 = textOf(execFields['策划']);
const 执行日期 = dateOf(execFields['执行日期']) || quote.执行日期_报价单 || '';
const 活动天数 = execFields['活动天数'] ?? quote.活动天数 ?? '';
const 活动名称 = quote.活动名称 || '';
const 出发地 = textOf(execFields['出发地']) || quote.出发地 || '';
const 目的地 = textOf(execFields['目的地']) || quote.目的地 || '';
const 执行人数 =
  execFields['执行人数'] != null && execFields['执行人数'] !== ''
    ? execFields['执行人数']
    : quote.人数 ?? '';
const 执行编号 = textOf(execFields['执行编号']);
const 付款方式 = clauses.join('\n');
const orderRecordId =
  execFields['关联订单']?.link_record_ids?.[0] || '';

requireText('订单号', 订单号);
requireText('单位(甲方名称)', 单位);
requireText('联系人', 联系人);
requireText('联系方式', 联系方式);
requireText('签约单位', signingUnit);
requireText('策划师', 策划师);
requireText('执行日期(活动日期)', 执行日期);
requireText('活动名称', 活动名称);
requireText('执行人数', 执行人数);
requireText('活动天数', 活动天数);
requireText('出发地', 出发地);
requireText('目的地', 目的地);
requireText('执行编号', 执行编号);
requireText('在线报价', textOf(execFields['在线报价']) || $('解析在线报价链接').first().json.spreadsheet_token);

if (!费用明细.length) errors.push('缺少费用明细');
if (!活动行程.length) errors.push('缺少活动行程');

const ok = errors.length === 0;
const errorMessage = errors.join('；');

return [
  {
    json: {
      ok,
      errors,
      error_message: errorMessage,
      合同生成回写值: ok ? '成功' : errorMessage,
      tenant_access_token: $('获取飞书Token').first().json.tenant_access_token,
      signing_unit: signingUnit,
      exec_record_id: execRecord.record_id || '',
      fields: {
        订单号,
        单位,
        联系人,
        联系方式,
        签约单位: signingUnit,
        策划师,
        合同价款: Number.isFinite(totalCost) ? totalCost : null,
        执行日期,
        活动天数,
        活动名称,
        出发地,
        目的地,
        执行人数,
        付款比例: payRaw,
        付款方式,
        费用明细,
        活动行程,
        执行编号,
        执行记录_id: execRecord.record_id || '',
        订单记录_id: orderRecordId,
        甲方地址: '',
        甲方税号: '',
      },
    },
  },
];

function cleanString(v) {
  if (v == null) return '';
  return String(v).trim();
}

function activityDaysNumber(v) {
  if (v == null || v === '') return null;
  const match = String(v).replace(/[,，\s]/g, '').match(/\d+(?:\.\d+)?/);
  if (!match) return null;
  const n = Number(match[0]);
  return Number.isFinite(n) ? n : null;
}

function dateToFeishuTimestamp(dateValue) {
  if (!dateValue) return null;
  const source = String(dateValue).trim();
  const match = source.match(/^(\d{4})[-年/](\d{1,2})[-月/](\d{1,2})(?:日)?$/);
  if (!match) return null;
  return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3])).getTime();
}

const src = $('合同信息聚合').first().json.fields;
const departure = cleanString(src['出发地']);
const destination = cleanString(src['目的地']);
const execDate = dateToFeishuTimestamp(src['执行日期']);
const activityDays = activityDaysNumber(src['活动天数']);
const population = src['执行人数'];
const fields = {
  电子版合同: {
    text: $input.first().json.document_name,
    link: $input.first().json.document_url,
  },
  合同生成: '成功',
};

if (departure) fields['出发地'] = [departure];
if (destination) fields['目的地'] = [destination];
if (execDate !== null) fields['执行日期'] = execDate;
if (activityDays !== null) fields['活动天数'] = activityDays;
if (population !== null && population !== undefined && population !== '') {
  fields['执行人数'] = population;
}

return { json: { fields } };

function parseSpreadsheetToken(field) {
  const candidates = [];

  function collect(value) {
    if (value == null) return;
    if (typeof value === 'string') {
      candidates.push(value.trim());
      return;
    }
    if (Array.isArray(value)) {
      value.forEach(collect);
      return;
    }
    if (typeof value === 'object') {
      for (const key of ['link', 'url', 'value', 'text', 'token']) {
        if (key in value) collect(value[key]);
      }
    }
  }

  collect(field);
  for (const candidate of candidates) {
    if (!candidate) continue;
    let decoded = candidate;
    try {
      decoded = decodeURIComponent(candidate);
    } catch {
      // keep original
    }
    const urlMatch = decoded.match(/\/sheets\/([A-Za-z0-9_-]+)/i);
    if (urlMatch) return urlMatch[1];
    if (
      /^[A-Za-z0-9_-]{10,}$/.test(decoded) &&
      !/\s/.test(decoded) &&
      !/^https?:/i.test(decoded)
    ) {
      return decoded;
    }
  }

  throw new Error('执行表「在线报价」中无法提取 spreadsheet_token');
}

const response = $input.first().json;
if (response.code != null && response.code !== 0) {
  throw new Error(
    '读取执行表失败 [' + response.code + ']: ' + (response.msg || '未知错误'),
  );
}

const record = response.data?.items?.[0];
if (!record) {
  throw new Error('未找到待生成合同的执行记录');
}

const onlineQuote = record.fields?.['在线报价'];
if (onlineQuote == null || onlineQuote === '') {
  throw new Error('执行表缺少「在线报价」链接');
}

const spreadsheetToken = parseSpreadsheetToken(onlineQuote);

return [
  {
    json: {
      spreadsheet_token: spreadsheetToken,
      exec_record_id: record.record_id || '',
      order_record_id: record.fields?.['关联订单']?.link_record_ids?.[0] || '',
    },
  },
];

const response = $input.first().json;
if (response.code != null && response.code !== 0) {
  throw new Error('查询在线报价工作表失败 [' + response.code + ']: ' + (response.msg || '未知错误'));
}
const sheets = (response.data?.sheets || []).filter((s) => s && s.hidden !== true);
const first = sheets[0] || (response.data?.sheets || [])[0] || {};
const sheetId =
  first.sheet_id ||
  first.sheetId ||
  first.sheet?.sheet_id ||
  '';
if (!sheetId) {
  throw new Error('在线报价电子表格中未找到 worksheet sheet_id');
}

return [{
  json: {
    spreadsheet_token: $('解析在线报价链接').item.json.spreadsheet_token,
    sheet_id: sheetId,
    sheet_title: first.title || '',
  },
}];

function parseOnlineQuoteValues(values) {
  if (!Array.isArray(values) || values.length === 0) {
    throw new Error('在线报价单元格数据为空');
  }

  function rawCell(row, index) {
    const value = Array.isArray(row) ? row[index] : undefined;
    if (value == null) return '';
    if (typeof value !== 'object') return value;
    if (value.value != null) {
      if (Array.isArray(value.value)) return value.value[0] ?? '';
      return value.value;
    }
    if (value.text != null) return value.text;
    return '';
  }

  function text(value) {
    if (value == null || value === '') return '';
    if (typeof value === 'string' || typeof value === 'number') {
      return String(value).trim();
    }
    if (Array.isArray(value)) return value.map(text).filter(Boolean).join('');
    if (typeof value === 'object') {
      if (value.value != null) return text(value.value);
      if (value.text != null) return text(value.text);
    }
    return '';
  }

  function cell(row, index) {
    return text(rawCell(row, index));
  }

  function numberOf(value) {
    if (typeof value === 'number') return Number.isFinite(value) ? value : null;
    const source = text(value);
    if (!source) return null;
    const normalized = source
      .replace(/[¥￥元,，\s]/g, '')
      .replace(/％/g, '%');
    if (/^-?\d+(?:\.\d+)?%$/.test(normalized)) {
      return Number(normalized.slice(0, -1)) / 100;
    }
    const number = Number(normalized);
    return Number.isFinite(number) ? number : null;
  }

  function rowTexts(row) {
    const width = Math.max(Array.isArray(row) ? row.length : 0, 9);
    return Array.from({ length: width }, (_, index) => cell(row, index));
  }

  function rowBlob(row) {
    return rowTexts(row).filter(Boolean).join(' ');
  }

  function findMeta(label, beforeIndex) {
    for (let rowIndex = 0; rowIndex < beforeIndex; rowIndex += 1) {
      const row = values[rowIndex];
      const texts = rowTexts(row);
      const labelIndex = texts.findIndex(
        (value) => value.replace(/\s*[:：]\s*$/, '').trim() === label,
      );
      if (labelIndex < 0) continue;
      for (let column = labelIndex + 1; column < texts.length; column += 1) {
        if (texts[column]) return rawCell(row, column);
      }
    }
    return '';
  }

  const detailHeaderIndex = values.findIndex((row) => {
    const blob = rowBlob(row);
    return (
      blob.includes('类目') &&
      blob.includes('物品名称') &&
      blob.includes('描述') &&
      blob.includes('数量') &&
      blob.includes('单价')
    );
  });
  if (detailHeaderIndex < 0) {
    throw new Error('在线报价中未找到明细表头（类目/物品名称/描述/数量/单价）');
  }

  const headerTexts = rowTexts(values[detailHeaderIndex]);
  const findColumn = (labels, fallback) => {
    const index = headerTexts.findIndex((value) =>
      labels.some((label) => value === label || value.includes(label)),
    );
    return index >= 0 ? index : fallback;
  };
  const columns = {
    category: findColumn(['类目', '分类'], 0),
    name: findColumn(['物品名称', '名称'], 1),
    description: findColumn(['描述', '内容'], 2),
    quantity: findColumn(['数量'], 3),
    unitPrice: findColumn(['单价'], 4),
    lineTotal: findColumn(['总价', '小计', '金额'], 5),
  };

  const totalIndex = values.findIndex(
    (row, index) => index > detailHeaderIndex && rowBlob(row).includes('活动总价'),
  );
  if (totalIndex < 0) {
    throw new Error('在线报价中未找到「活动总价」行');
  }

  const totalRow = values[totalIndex];
  let activityTotal = null;
  for (const column of [3, 4, 5, 6, 7, 8]) {
    const candidate = numberOf(rawCell(totalRow, column));
    if (candidate != null) {
      activityTotal = candidate;
      break;
    }
  }
  if (activityTotal == null) {
    throw new Error('在线报价「活动总价」行没有可读取的公式计算值（请确认已填单价且用 UnformattedValue 读取）');
  }

  const feeObjects = [];
  let lastCategory = '';

  for (let index = detailHeaderIndex + 1; index < totalIndex; index += 1) {
    const row = values[index];
    const categoryValue = cell(row, columns.category);
    if (categoryValue) lastCategory = categoryValue.replace(/^\d+\s*[.、．]\s*/, '').trim();
    const category = lastCategory || '费用';
    const name = cell(row, columns.name);
    const description = cell(row, columns.description)
      .replace(/[\r\n]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    const quantity = numberOf(rawCell(row, columns.quantity));
    const unitPrice = numberOf(rawCell(row, columns.unitPrice));
    const lineTotal = numberOf(rawCell(row, columns.lineTotal));
    const isTax = /税费|服务费/.test(category + ' ' + name);

    if (!name && !description && quantity == null && unitPrice == null && lineTotal == null) {
      continue;
    }
    if (!isTax && lineTotal === 0) continue;

    feeObjects.push({
      分类: category,
      名称: name || '(未命名)',
      描述: description,
      数量: quantity,
      单价: unitPrice,
      总价: lineTotal,
    });
  }

  const itinerarySectionIndex = values.findIndex(
    (row, index) => index > totalIndex && rowBlob(row).includes('活动行程'),
  );
  if (itinerarySectionIndex < 0) {
    throw new Error('在线报价中未找到「活动行程」区域');
  }

  const itineraryHeaderIndex = values.findIndex((row, index) => {
    if (index <= itinerarySectionIndex) return false;
    const blob = rowBlob(row);
    return blob.includes('日期') && blob.includes('时间') && blob.includes('内容');
  });
  if (itineraryHeaderIndex < 0) {
    throw new Error('在线报价中未找到行程表头（日期/时间/内容）');
  }

  const itineraryHeaders = rowTexts(values[itineraryHeaderIndex]);
  const itineraryColumns = {
    date: itineraryHeaders.findIndex((value) => value.includes('日期')),
    time: itineraryHeaders.findIndex((value) => value.includes('时间')),
    content: itineraryHeaders.findIndex((value) => value.includes('内容')),
  };
  const tripObjects = [];
  let lastDay = '';

  for (let index = itineraryHeaderIndex + 1; index < values.length; index += 1) {
    const row = values[index];
    const dateValue = cell(row, itineraryColumns.date >= 0 ? itineraryColumns.date : 0);
    const timeValue = cell(row, itineraryColumns.time >= 0 ? itineraryColumns.time : 1);
    const content = cell(row, itineraryColumns.content >= 0 ? itineraryColumns.content : 2)
      .replace(/[\r\n]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    if (!dateValue && !timeValue && !content) continue;
    if (dateValue) lastDay = dateValue;
    if (!content) continue;

    const day = /^d\d+$/i.test(lastDay)
      ? lastDay.toLowerCase().replace(/^d/, 'day')
      : lastDay || '行程';

    tripObjects.push({
      日期: day,
      时间: timeValue,
      内容: content,
    });
  }

  const activityName = text(findMeta('活动名称', detailHeaderIndex));
  const peopleRaw = findMeta('报价人数', detailHeaderIndex);
  const people = numberOf(peopleRaw) ?? text(peopleRaw);
  const activityDays = text(findMeta('活动天数', detailHeaderIndex));
  const activityDate = text(findMeta('活动日期', detailHeaderIndex));
  const originDestination = text(findMeta('出发地目的地', detailHeaderIndex));
  const [departure = '', destination = ''] = originDestination
    .split(/[-—–～~]/)
    .map((value) => value.trim());

  return {
    活动名称: activityName,
    人数: people,
    活动天数: activityDays,
    执行日期_报价单: activityDate,
    出发地: departure,
    目的地: destination,
    出发地目的地: originDestination,
    活动总价: activityTotal,
    报价明细条目: feeObjects,
    活动行程条目: tripObjects,
    extracted: [
      { key: '活动名称', value: activityName },
      { key: '人数', value: people },
      { key: '活动天数', value: activityDays },
      { key: '执行日期', value: activityDate },
      {
        key: '出发地目的地',
        value: originDestination,
        出发地: departure,
        目的地: destination,
      },
      { key: '活动总价', value: activityTotal },
      { key: '报价明细条目', value: feeObjects },
      { key: '活动行程条目', value: tripObjects },
    ],
  };
}

const response = $input.first().json;
if (response.code != null && response.code !== 0) {
  throw new Error('读取在线报价单元格失败 [' + response.code + ']: ' + (response.msg || '未知错误'));
}
const valueRanges = response.data?.valueRanges || [];
const values = valueRanges[0]?.values || [];
return [{ json: parseOnlineQuoteValues(values) }];

